function solve(arr) {
  const d = { next: null };
  let tail = d, i = 0;
  while (i < arr.length) {
    let j = i;
    while (j < arr.length && arr[j] === arr[i]) j++;
    if (j - i === 1) { tail.next = { val: arr[i], next: null }; tail = tail.next; }
    i = j;
  }
  const out = [];
  for (let p = d.next; p; p = p.next) out.push(p.val);
  return out;
}
